    print(f"Example {i}: '{inp}' vs '{out}'")
    if inp != out:
        # Find where they differ
        min_len = min(len(inp), len(out))
        diff_pos = None
        for j in range(min_len):
            if inp[j] != out[j]:
                diff_pos = j
                break
        if diff_pos is not None:
            print(f"  First difference at position {diff_pos}: '{inp[diff_pos]}' -> '{out[diff_pos]}'")
        else:
            if len(inp) > len(out):
                print(f"  Truncated at position {min_len}: '{inp[min_len:]}' removed")
            else:
                print(f"  Extended at position {min_len}: '{out[min_len:]}' added")
    else:
        print("  No change")

