inputs = ['uz', 'yv', 'eweuvi', 'bfw', 'zukaz']
outputs = ['yz', 'yv', 'eceyvi', 'bfc', 'zykaz']

# Test that our rules don't over-apply
rules = [('u', 'y'), ('w', 'c')]

# Check each input to see if any other characters would be affected
print("Checking for over-applications:")
for i, inp in enumerate(inputs):
    original = inp
    result = inp
    for rule in rules:
        result = result.replace(rule[0], rule[1])

    print(f"Input: '{original}' -> Output: '{result}' (Expected: '{outputs[i]}')")

    # Check if we're affecting anything we shouldn't
    if result != outputs[i]:
        print(f"  ERROR: Expected '{outputs[i]}', got '{result}'")
    else:
        print(f"  ✓ Correct")

print("\nChecking if any other strings would be incorrectly modified:")
# Check if 'u' appears elsewhere in inputs/outputs that shouldn't be changed
all_strings = inputs + outputs
for s in all_strings:
    if 'u' in s and s not in ['uz', 'zukaz']:
        print(f"String '{s}' contains 'u' but shouldn't be affected by our rule")

for s in all_strings:
    if 'w' in s and s not in ['eweuvi', 'bfw']:
        print(f"String '{s}' contains 'w' but shouldn't be affected by our rule")

